content.query:
let selected = customEvents
| where timestamp {TimeRange};
let eventViews = toscalar(selected | where name == "view_event" | count);
let calendarAdds = toscalar(selected | where name == "add_to_calendar" | count);
let directions = toscalar(selected | where name == "get_directions" | count);
let shares = toscalar(selected | where name == "share" | count);
let organizerClicks = toscalar(selected | where name == "outbound_click" | where tostring(customDimensions.method) in ("website", "phone", "email") | count);
union
(print StepOrder = 1, Step = "Event pages viewed", Count = eventViews),
(print StepOrder = 2, Step = "Added to calendar", Count = calendarAdds),
(print StepOrder = 3, Step = "Got directions", Count = directions),
(print StepOrder = 4, Step = "Shared", Count = shares),
(print StepOrder = 5, Step = "Clicked organizer website, phone, or email", Count = organizerClicks)
| extend PercentOfEventViews = iif(eventViews == 0, real(null), round(100.0 * Count / eventViews, 1))
| order by StepOrder asc
| project Step, Count, PercentOfEventViews
